Close the handle and delete it from handles Map before throwing the error:

if (stat.size > 1_000_000) {
  await handle.close();
  handles.delete(id);
  throw new Error(`job ${id} log is too large to append to`);
}

Close the open file handle and return a failure status (e.g., { ok: false, error }) when an error occurs:

async function runOne(id) {
  let handle;
  try {
    handle = await openJob(id);
    await handle.write("started\n");
    return { id, ok: true };
  } catch (error) {
    if (handle) {
      try { await handle.close(); } catch {}
      handles.delete(id);
    }
    return { id, ok: false, error: error.message };
  }
}

Add a .catch handler to the fs.appendFile promise and return or store the interval ID so it can be cleared when the job finishes or fails:

function startHeartbeat(id) {
  const interval = setInterval(() => {
    fs.appendFile(`/var/jobs/${id}.beat`, `${Date.now()}\n`)
      .catch((err) => {
        console.error(`Heartbeat write failed for job ${id}:`, err);
        clearInterval(interval);
      });
  }, 1000);
  return interval;
}

Validate the job id to ensure it matches a strict alphanumeric/safe pattern before interpolating it into file system path strings:

if (typeof id !== 'string' || !/^[a-zA-Z0-9-_]+$/.test(id)) {
  throw new Error('Invalid job ID format');
}

